/**
 * headline.ts: the plain sentence and the text under it for an ask, from the tool and its input.
 *
 * The dialog shows a sentence, then the command or path alone. A guard ask brings
 * its own sentence, so the one here is for every other ask: a core ask's own
 * reason is long and full of paths.
 */

export type Headline = {
  sentence: string
  /** What the dialog shows beneath the sentence: the command, the path, the address. */
  text: string
  /** A write asks `Allow this write?`, everything else `Allow this command?`. */
  kind: 'command' | 'write'
}

const WRITES: Record<string, string> = {
  Edit: 'Edits this file.',
  MultiEdit: 'Edits this file.',
  Write: 'Writes this file.',
  NotebookEdit: 'Edits this notebook.',
}

// A command starts at the text's start, a new line, or after `;`, `&`, `|` or `(`.
const START = String.raw`(?:^|[\n;&|(])\s*`
const COMMIT = new RegExp(`${START}git\\s+commit\\b`)
const PUSH = new RegExp(`${START}git\\s+push\\b`)
const PUBLISH = new RegExp(`${START}(?:npm|pnpm|yarn|cargo|gem|twine)\\s+(?:publish|push|upload)\\b`)

const SAVE = new RegExp(`${START}(?:u|util)\\s+(?:g|git)\\s+save\\b`)

/**
 * `util git save` stages, commits and pushes inside one script, so the rules on
 * `git commit` never see it. Its flags are read up to the first quote, where
 * the message starts.
 */
function saveSentence(command: string): string {
  const flags = command.split(/["']/)[0]!
  if (/\s--dry-run\b/.test(flags)) return 'Shows the git commands a save would run.'
  const what = /\s(?:-p|--path)\s/.test(flags) ? 'the listed paths' : 'everything'
  const it = what === 'everything' ? 'it' : 'them'
  return /\s(?:-n|--no-push)\b/.test(flags) ? `Stages ${what} and commits ${it}.` : `Stages ${what}, commits ${it} and pushes.`
}

/** The sentence for a shell command: a publish, a save, a commit, a push or both, found anywhere in the command. */
function bashSentence(command: string): string {
  if (PUBLISH.test(command)) return 'Publishes a package.'
  if (SAVE.test(command)) return saveSentence(command)
  const commit = COMMIT.test(command)
  const push = PUSH.test(command)
  if (commit && push) return 'Makes a git commit and pushes it.'
  if (commit) return 'Makes a git commit.'
  if (push) return 'Pushes commits to a remote.'
  return 'Runs a shell command.'
}

const field = (input: unknown, name: string): string | undefined => {
  const value = (input as Record<string, unknown> | null | undefined)?.[name]
  return typeof value === 'string' ? value : undefined
}

/** The one field that names what the call touches. Undefined for a tool with none. */
export function mainField(input: unknown): string | undefined {
  for (const name of ['command', 'file_path', 'notebook_path', 'url', 'query']) {
    const value = field(input, name)
    if (value !== undefined) return value
  }
  return undefined
}

/** Other tools: one `name: value` line per field, since JSON reads badly in a dialog. */
function fieldLines(input: unknown): string {
  if (typeof input !== 'object' || input === null) return ''
  return Object.entries(input)
    .map(([name, value]) => `${name}: ${typeof value === 'string' ? value : JSON.stringify(value)}`)
    .join('\n')
}

/** The headline for a call. `Bash` gets a sentence by command only for a commit, a push and a publish. */export function headline(tool: string, input: unknown): Headline {
  if (tool === 'Bash') {
    const command = field(input, 'command') ?? ''
    return { sentence: bashSentence(command), text: command, kind: 'command' }
  }
  const write = WRITES[tool]
  if (write) return { sentence: write, text: mainField(input) ?? '', kind: 'write' }
  if (tool === 'Read') return { sentence: 'Reads this file.', text: mainField(input) ?? '', kind: 'command' }
  if (tool === 'WebFetch') return { sentence: 'Fetches this page.', text: mainField(input) ?? '', kind: 'command' }
  if (tool === 'WebSearch') return { sentence: 'Searches the web.', text: mainField(input) ?? '', kind: 'command' }
  return { sentence: `Calls the tool ${tool}.`, text: fieldLines(input), kind: 'command' }
}

/**
 * The sentence for a write the guard asked about. The guard's own sentence
 * does not survive: Claude Code swaps in its long `requested permissions` text.
 */
export function guardedSentence(tool: string, file: string): string {
  if (/(^|\/)\.ssh\//.test(file)) return 'Writes into ~/.ssh.'
  return `${(WRITES[tool] ?? 'Edits this file.').replace(/\.$/, '')}, which could switch the guard off.`
}

/** The dialog's own question, which the draw rewrites to. */
export const questionFor = (kind: Headline['kind']) => (kind === 'write' ? 'Allow this write?' : 'Allow this command?')

files.hooks/log.ts:
/**
 * log.ts: one line per ask for `~/.flow/logs/permissions/<year>-<month>.jsonl`.
 *
 * `flow audit permissions` (scripts/lib/audit/permissions.js) reads it. It skips
 * a line without a string `source` and `answer`, counts `answer: "auto-allow"`
 * apart from asks, and exempts a `source: "rule"` line whose `rule` is spelled
 * as in home/settings.json → `permissions.ask`.
 */

export type Source = 'guard' | 'rule' | 'core'
export type LogAnswer = 'allow' | 'refuse' | 'note' | 'auto-allow' | 'nobody'

export type LogFields = {
  at: Date
  project: string
  session: string
  /** The subagent's id, else `main`. */
  agent?: string
  tool: string
  source: Source
  /** The sentence the dialog showed. */
  headline: string
  command: string
  /** The settings rule that asked, spelled as in `permissions.ask`. */
  rule?: string
  answer: LogAnswer
  /** How long the dialog was open. Absent where none opened. */
  ms?: number
}

const MAX_COMMAND = 200
const SESSION_WIDTH = 8

/** `guard` when the guard's hook asked, `rule` when a settings rule did, else Claude Code itself. */
export function sourceOf(hook: string | undefined, rule: string | undefined): Source {
  if (hook === 'PreToolUse') return 'guard'
  return rule === undefined ? 'core' : 'rule'
}

/** One JSON line with no trailing newline. `at` is ISO UTC with no milliseconds. */
export function logLine(fields: LogFields): string {
  return JSON.stringify({
    at: fields.at.toISOString().replace(/\.\d{3}Z$/, 'Z'),
    project: fields.project,
    session: fields.session.slice(0, SESSION_WIDTH),
    agent: fields.agent ?? 'main',
    tool: fields.tool,
    source: fields.source,
    headline: fields.headline.replace(/\.$/, ''),
    command: fields.command.slice(0, MAX_COMMAND),
    rule: fields.rule,
    answer: fields.answer,
    ms: fields.ms,
  })
}

/** The month's file under the Flow home, named by UTC month as `at` is. */
export function logPath(home: string, now: Date): string {
  const month = String(now.getUTCMonth() + 1).padStart(2, '0')
  return `${home}/logs/permissions/${now.getUTCFullYear()}-${month}.jsonl`
}

/**
 * The command that appends `line` to `path` and makes the folder first.
 * `$.fs` has no append, and reading then writing loses a line when two
 * sessions log at once.
 */
export const appendCommand = (line: string, path: string): string[] => [
  'bash',
  '-c',
  'mkdir -p "$(dirname "$2")" && printf "%s\\n" "$1" >> "$2"',
  'log',
  line,
  path,
]

files.hooks/note.ts:
/**
 * note.ts: which mentioned files are notes left for another session.
 *
 * `/flow:handoff` writes a note for a session that was not here into
 * `.flow/handoffs/`. The session that opens it reads it as a mention, and the
 * mod removes the file once that turn ends with an answer.
 */

/** True for a file under the session's `.flow/handoffs/`. A path with `..` in it never counts. */
export function isNote(root: string, path: string): boolean {
  const base = `${root.replace(/\/+$/, '')}/.flow/handoffs/`
  return path.startsWith(base) && path.length > base.length && !path.includes('/../')
}

files.hooks/notes.ts:
/**
 * notes.ts: the rows of the `#` list, built from the files in `~/.flow/notes/`.
 *
 * `flow notes` writes those files (scripts/lib/notes.js). Typing `#` in the
 * prompt box lists the labels with their counts, then the newest notes, and
 * `#board` narrows the list. Taking a label row writes `#label`, and taking a
 * note row writes an `@` mention of its file. The query matches as
 * scripts/lib/query.js does: a word must appear in the text, the labels or the
 * project.
 */
import { mention } from './drag'

export type Note = {
  path: string
  changed: number
  title: string
  labels: string[]
  project: string
  /** The whole file, lowercased, for matching. */
  haystack: string
}

export type Row = { text: string; label: string; description: string }

// A colon later than this in the first line belongs to the sentence, not to a title.
const TITLE_COLON_MAX = 60
const TITLE_WIDTH = 60
const MAX_LABELS = 6
const MAX_NOTES = 8

const unquote = (value: string) => value.trim().replace(/^(["'])(.*)\1$/, '$2')

/** A note's header and text. The header holds `date`, `labels: [a, b]` and `project`. */
function split(raw: string): { header: Map<string, string>; body: string } {
  const header = new Map<string, string>()
  const lines = raw.replace(/^﻿/, '').split('\n')
  if (lines[0]?.trim() !== '---') return { header, body: raw.trim() }
  const end = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
  if (end === -1) return { header, body: raw.trim() }
  for (const line of lines.slice(1, end)) {
    const at = line.indexOf(':')
    if (at > 0) header.set(line.slice(0, at).trim(), line.slice(at + 1).trim())
  }
  return { header, body: lines.slice(end + 1).join('\n').trim() }
}

/** The words before the first `: ` of the first line, else the whole first line. */
export function titleOf(body: string): string {
  const line = (body.split('\n').find((l) => l.trim()) ?? '').trim()
  const cut = line.match(new RegExp(`^(.{1,${TITLE_COLON_MAX}}?):(?:\\s|$)`))
  return (cut?.[1]?.trim() || line)
}

/** One note file. `project` is `global` where the header names none. */
export function parseNote(path: string, changed: number, raw: string): Note {
  const { header, body } = split(raw)
  const inner = (header.get('labels') ?? '').replace(/^\[|\]$/g, '')
  const labels = inner.split(',').map((l) => unquote(l).toLowerCase()).filter(Boolean)
  const project = unquote(header.get('project') ?? '') || 'global'
  return {
    path,
    changed,
    title: titleOf(body),
    labels,
    project,
    haystack: `${body}\n${labels.join(' ')}\n${project}`.toLowerCase(),
  }
}

const cut = (text: string, width: number) => (text.length > width ? `${text.slice(0, width - 1).trimEnd()}…` : text)

/** The word a row's title starts with: none for the current project, `global:` or `<project>:` for the rest. */
const prefixOf = (note: Note, here: string) =>
  note.project.toLowerCase() === here.toLowerCase() ? '' : `${note.project}: `

/**
 * The rows for the token typed. Label rows come first, the most used first,
 * then notes: the current project's, then the rest, each newest change first.
 */
export function rows(notes: readonly Note[], token: string, here: string): Row[] {
  const query = token.replace(/^#/, '').toLowerCase()

  const counts = new Map<string, number>()
  for (const note of notes) for (const label of note.labels) counts.set(label, (counts.get(label) ?? 0) + 1)
  const labelRows: Row[] = [...counts]
    .filter(([label]) => label.includes(query))
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, MAX_LABELS)
    .map(([label, count]) => ({ text: `#${label}`, label: `#${label}`, description: `${count} ${count === 1 ? 'note' : 'notes'}` }))

  const ownFirst = (note: Note) => (note.project.toLowerCase() === here.toLowerCase() ? 0 : 1)
  const noteRows: Row[] = notes
    .filter((note) => note.haystack.includes(query))
    .sort((a, b) => ownFirst(a) - ownFirst(b) || b.changed - a.changed)
    .slice(0, MAX_NOTES)
    .map((note) => ({
      text: `${mention(note.path)} `,
      label: cut(`${prefixOf(note, here)}${note.title}`, TITLE_WIDTH),
      description: note.labels.map((l) => `#${l}`).join(' '),
    }))

  return [...labelRows, ...noteRows]
}

files.hooks/pane.ts:
/**
 * pane.ts: the logic of the permission dialog, with no call to the engine.
 *
 * What the dialog says, folds and cuts, what the draw needs, and the verdict of a
 * refusal that the second hook (`classic.PermissionRequest`) answers from.
 * Both live in module state: the draw is keyed by the exact question text, the
 * verdict by the tool and what it touches, since that hook sees no call id.
 */
import type { PermissionRequestDecision } from 'claude-code'
import { mainField } from './headline'

/** The dialog cuts its question at 2000 characters with a bare `…`, so the mod cuts first. */
const MAX_QUESTION = 1999
/** A sentence plus 11 lines of command fit the 12 rows the engine lets a draw use. */
const MAX_COLOUR_LINES = 11
const WRITE_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const OWN_ID = 'toolu_plugin_'
const NOBODY = 'No one is here to ask. Choose another way, or stop.'

export type Shown = {
  /** The text given to `$.ui.ask`: the sentence, a blank line, the text. */
  question: string
  sentence: string
  /** The text as shown, with the notice of what was cut on its last line. */
  text: string
  cut: boolean
}

/** Ends a text the mod cut. No count: the user only needs to know that not all of it shows. */
const CUT_NOTICE = '… the rest is not shown'

/**
 * The question for a sentence and the text beneath it. A text too long for the
 * dialog is cut on a line, or where one line stands when no break fits, and
 * ends with a line saying the rest is not shown.
 */
export function questionText(sentence: string, text: string): Shown {
  const full = `${sentence}\n\n${text}`
  if (full.length <= MAX_QUESTION) return { question: full, sentence, text, cut: false }
  const room = Math.max(0, MAX_QUESTION - sentence.length - 2 - 1 - CUT_NOTICE.length)
  const head = text.slice(0, room)
  const newline = head.lastIndexOf('\n')
  const shown = `${newline < 0 ? head : head.slice(0, newline)}\n${CUT_NOTICE}`
  return { question: `${sentence}\n\n${shown}`, sentence, text: shown, cut: true }
}

const nonBlank = (text: string) => text.split('\n').filter((line) => line.trim()).length

/** Whether the draw keeps the blank lines: each costs a row, so only while every line fits. */
export const keepsBlanks = (text: string) => text.split('\n').length <= MAX_COLOUR_LINES

/** Whether the draw can carry the text in colour: nothing cut, and 11 lines or fewer, not counting the blank ones. */
export const drawsInColour = (shown: Shown) => !shown.cut && nonBlank(shown.text) <= MAX_COLOUR_LINES

/**
 * A command too long to colour whole, folded: up to its 11th non-blank line,
 * with `…` ending that line. Undefined for a command that fits.
 */
export function foldedText(text: string): string | undefined {
  if (nonBlank(text) <= MAX_COLOUR_LINES) return undefined
  const lines = text.split('\n')
  let seen = 0
  let end = 0
  for (; end < lines.length; end++) if (lines[end]!.trim() && ++seen === MAX_COLOUR_LINES) break
  return `${lines.slice(0, end + 1).join('\n')}…`
}

export type Draw = {
  sentence: string
  text: string
  colour: boolean
  /** The question the dialog is rewritten to. */
  asks: string
}

const draws = new Map<string, { draw: Draw; open: number }>()

/** Keeps what the draw needs while the dialog is open. Two asks with the same text share one entry. */
export function rememberDraw(question: string, draw: Draw): void {
  const kept = draws.get(question)
  if (kept) kept.open++
  else draws.set(question, { draw, open: 1 })
}

export const recallDraw = (question: string): Draw | undefined => draws.get(question)?.draw

export function forgetDraw(question: string): void {
  const kept = draws.get(question)
  if (!kept) return
  if (--kept.open <= 0) draws.delete(question)
}

/** The mod's own question carries a `toolu_plugin_` id, the model's own a `toolu_` one. */
export const isOwnQuestion = (requestId: string) => requestId.startsWith(OWN_ID)

export type Answer = 'allow' | 'refuse' | 'note'

/** The answer by its label. Any other text came from the typed row. */
export const classify = (label: string): Answer => (label === 'Allow' ? 'allow' : label === 'Refuse' ? 'refuse' : 'note')

export type Verdict = { interrupt: true } | { interrupt: false; note: string }

const verdicts = new Map<string, Verdict>()

/** Tool and what it touches. The second hook has the tool's input but no call id. */
export const verdictKey = (tool: string, input: unknown) => `${tool}\n${mainField(input) ?? JSON.stringify(input ?? {})}`

export const storeVerdict = (key: string, verdict: Verdict) => void verdicts.set(key, verdict)

/** The verdict for a call, removed as it is read. */
export function takeVerdict(key: string): Verdict | undefined {
  const verdict = verdicts.get(key)
  verdicts.delete(key)
  return verdict
}

/** A refusal stops the turn. A typed note denies without stopping, and the agent reads the note. */
export function denyFor(verdict: Verdict): PermissionRequestDecision {
  if (verdict.interrupt) return { behavior: 'deny', message: 'The user refused this call.', interrupt: true }
  return { behavior: 'deny', message: `The user refused this call and wrote: "${verdict.note}".` }
}

/** What an ask answers where no one can: a deny the agent reads, with no interrupt. */
export const nobodyReason = () => NOBODY

type Decided = { decision: string; hook?: string; rule?: string }

// A loaded mod's folder is protected like `.claude`. The manifests stay asked: they decide which hooks load.
const MOD_FOLDER = /(^|\/)mods\/flow-session\//
const MOD_MANIFEST = /(^|\/)mods\/flow-session\/(\.claude-plugin\/plugin\.json|hooks\/hooks\.json)$/

/**
 * A core ask on a write under a `.claude` folder, or from the main agent under
 * this mod's folder bar its manifests, with no guard reason and no settings
 * rule behind it. Claude Code asks for every such write, and the mod's allow
 * is the only way to remove that ask.
 */
export function isAutoAllow(tool: string, input: unknown, decided: Decided, agentId?: string): boolean {
  if (decided.decision !== 'ask' || decided.hook === 'PreToolUse' || decided.rule !== undefined) return false
  if (!WRITE_TOOLS.has(tool)) return false
  const file = mainField(input) ?? ''
  if (/(^|\/)\.claude\//.test(file)) return true
  return agentId === undefined && MOD_FOLDER.test(file) && !MOD_MANIFEST.test(file)
}

/** Files whose guard ask got a yes this session. Lost on a restart, which asks again. */
const covered = new Set<string>()

/** The file a write asked about by the guard touches, or undefined for any other ask. */
export function guardedWrite(tool: string, input: unknown, decided: Decided): string | undefined {
  if (decided.decision !== 'ask' || decided.hook !== 'PreToolUse' || !WRITE_TOOLS.has(tool)) return undefined
  return mainField(input)
}

export const isCovered = (file: string) => covered.has(file)

export const cover = (file: string) => void covered.add(file)

files.hooks/wrap-up.ts:
/**
 * wrap-up.ts: when the mod tells the agent its context size, and what it says.
 *
 * Answers get worse long before the window fills, so the limit follows the
 * work, never the window. From 30k under the limit the mod gives the size every
 * 10k (`Context 140k/170k`), so the agent hands off before a large step instead
 * of in the middle of it. At the limit it asks for the restart, then again every
 * 20k past it. It replaces `scripts/hooks/context-check.js`, which read the
 * size from the session file.
 */
import { restartSteps } from './ask'

const LIMIT = 170000
const STEP = 20000
export const LEAD = 30000
const SIZE_STEP = 10000

/** Whole thousands, such as `152k`. */
export const kilo = (tokens: number) => `${Math.round(tokens / 1000)}k`

const parse = (text: string | undefined): Record<string, unknown> => {
  try {
    const value: unknown = JSON.parse(text ?? '')
    return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {}
  } catch {
    return {}
  }
}

/**
 * `wrapUp` and `wrapUpAt` from the text of `~/.flow/settings.json` and
 * `settings.local.json`. A switch is read from the first file alone, as
 * `scripts/lib/settings.js` does, and the local file wins for the limit.
 */
export function wrapUpSettings(globalText?: string, localText?: string): { wrapUp: boolean; limit: number } {
  const global = parse(globalText)
  const set = Number({ ...global, ...parse(localText) }.wrapUpAt)
  return { wrapUp: global.wrapUp !== false, limit: set > 0 ? set : LIMIT }
}

/**
 * True from `LEAD` under the limit while the wrap-up is on: the band then offers the restart. The
 * button is for restarting by hand ahead of the automatic restart at the limit.
 */
export const offersRestart = (tokens: number | undefined, limit: number, on: boolean): boolean =>
  on && tokens !== undefined && tokens >= Math.max(limit - LEAD, 0)

/**
 * The line to send, or undefined. `before` is the size at the last check, 0 at the first.
 * `handoffFresh` is true while a handoff stands and nothing changed after it.
 */
export function wrapUpLine(before: number, now: number, limit: number, handoffFresh = false): string | undefined {
  const size = `Context ${kilo(now)}/${kilo(limit)}`
  if (now < limit) {
    const from = Math.max(limit - LEAD, 0)
    if (now < from) return undefined
    const notice = from + Math.floor((now - from) / SIZE_STEP) * SIZE_STEP
    return before >= notice ? undefined : size
  }
  const mark = limit + Math.floor((now - limit) / STEP) * STEP
  if (before >= mark) return undefined
  const next = restartSteps(handoffFresh)
  if (before < limit) return `${size}. At the next checkpoint: ${next}.`
  return `${size}. Finish this step, then ${next}.`
}

files.hooks/band-mock.ts:
/**
 * band-mock.ts: the band's test scenarios, switched by `/band`.
 *
 * The scenarios are the user's to edit, in `band-scenarios.json` beside the mod's manifest.
 * `/band` reads that file on each run and draws the chosen scenario with the same code as the
 * real band. Nothing here touches a ticket or the saved record.
 */
import type { Entry } from '../types'

export type Scenario = {
  entries: Entry[]
  issues: number
  /** A row width that replaces the real one. */
  columns?: number
  /** Draws the Restart button, as if the context were past the wrap-up limit. */
  restart: boolean
}

type RawBadge = { id?: unknown; slug?: unknown; word?: unknown; done?: unknown; acting?: unknown }
type Raw = { badges?: unknown; issues?: unknown; columns?: unknown; restart?: unknown }

const toEntry = (badge: RawBadge): Entry | undefined => {
  if (typeof badge.id !== 'string' || typeof badge.slug !== 'string' || typeof badge.word !== 'string') return undefined
  return {
    id: badge.id,
    name: `${badge.id}-${badge.slug}`,
    word: badge.word,
    isDone: badge.done === true,
    acting: badge.acting === true,
  }
}

/** The scenarios in the file's text, or why it could not be read. A scenario with no valid badge is left out. */
export function parseScenarios(text: string): { scenarios: Record<string, Scenario>; error?: string } {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch (error) {
    return { scenarios: {}, error: `band-scenarios.json is not valid JSON: ${error instanceof Error ? error.message : String(error)}` }
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return { scenarios: {}, error: 'band-scenarios.json must hold an object of scenarios.' }
  const scenarios: Record<string, Scenario> = {}
  for (const [name, value] of Object.entries(raw)) {
    const item = value as Raw
    const entries = (Array.isArray(item.badges) ? item.badges : []).map((badge) => toEntry(badge as RawBadge)).filter((entry): entry is Entry => entry !== undefined)
    if (!entries.length) continue
    scenarios[name] = {
      entries,
      issues: typeof item.issues === 'number' ? item.issues : 0,
      restart: item.restart === true,
      ...(typeof item.columns === 'number' && { columns: item.columns }),
    }
  }
  return { scenarios }
}

/** What `/band <args>` asks for. */
export type MockCommand =
  | { show: string }
  | { off: true }
  | { acting: true }
  | { list: true }
  | { help: true }

/**
 * Reads the command's arguments. A bare `/band` switches the mock off when it is on, else shows the
 * scenario last shown (or the first). `next` steps from the one shown.
 */
export function parseMock(args: string, names: readonly string[], current: string | undefined, last: string | undefined): MockCommand {
  const word = args.trim().toLowerCase()
  const first = names[0]
  if (word === 'off') return { off: true }
  if (word === 'act') return { acting: true }
  if (word === 'list') return { list: true }
  if (word === '' || word === 'on') {
    if (word === '' && current) return { off: true }
    const back = last && names.includes(last) ? last : first
    return back ? { show: back } : { help: true }
  }
  if (word === 'next') {
    const at = current ? names.indexOf(current) : -1
    const next = names[(at + 1) % names.length]
    return next ? { show: next } : { help: true }
  }
  const byNumber = /^\d+$/.test(word) ? names[Number(word) - 1] : undefined
  if (byNumber) return { show: byNumber }
  return names.includes(word) ? { show: word } : { help: true }
}

/** One line a scenario: its badges' words and what else it draws. */
export function describeScenario(name: string, scenario: Scenario): string {
  const words = scenario.entries.map((entry) => `${entry.id} ${entry.word}`).join(', ')
  const more = [scenario.issues ? `${scenario.issues} issues` : '', scenario.columns ? `${scenario.columns} columns` : '', scenario.restart ? 'restart button' : ''].filter(Boolean)
  return `${name}: ${words}${more.length ? `; ${more.join(', ')}` : ''}`
}

export const usage = (names: readonly string[]) =>
  `/band switches the test band on or off. /band <number>, next, list, act (cycles: wave and spinner, wave alone, spinner alone, off), off, clear (empties the real band). Scenarios: ${names.map((name, i) => `${i + 1} ${name}`).join(', ') || 'none'}.`

/** The entries as shown: with the wave forced on every open badge while `acting` is switched on. */
export const withActing = (entries: readonly Entry[], acting: boolean): Entry[] =>
  entries.map((entry) => (acting && !entry.isDone ? { ...entry, acting: true } : entry))

files.hooks/band-model.ts:
/**
 * band-model.ts: what the band holds and how it lays out, with nothing drawn here.
 *
 * The ticket started last sits leftmost, so the order is the start order. A ticket never
 * leaves from being idle: it leaves at once when parked or dropped, and a closed one
 * (`DONE ✓`) leaves when the next ticket starts. The band is one row. The layout takes the first
 * of three looks that fits it, and folds what still does not fit into `+N`.
 */
import type { Entry } from '../types'
import type { Ticket } from './ticket'

export const DONE_WORD = 'DONE ✓'

/**
 * A ticket's file was read. `lights` is true when the command is `flow start` on the ticket:
 * it goes leftmost, and the closed badges leave. A ticket only read keeps its place.
 */
export function apply(entries: readonly Entry[], ticket: Ticket, lights: boolean): Entry[] {
  const at = entries.findIndex((entry) => entry.id === ticket.id)
  const kept = at === -1 ? undefined : entries[at]
  if (ticket.status === 'done') {
    if (!kept) return [...entries]
    return entries.map((entry) => (entry === kept ? { ...kept, name: ticket.name, word: DONE_WORD, isDone: true, acting: false } : entry))
  }
  if (ticket.status !== 'in-progress') return entries.filter((entry) => entry !== kept)
  if (!kept && !lights) return [...entries]
  const next: Entry = { ...(kept ?? { id: ticket.id, acting: false }), name: ticket.name, word: ticket.word, isDone: false }
  if (!lights) return entries.map((entry) => (entry === kept ? next : entry))
  return [next, ...entries.filter((entry) => entry !== kept && !entry.isDone)]
}

/**
 * The badge the session is working on: the leftmost open one, which is the one started last.
 * When it closes, the next one started before it takes over. A closed badge is never current.
 */
export const currentId = (entries: readonly Entry[]): string | undefined => entries.find((entry) => !entry.isDone)?.id

/** Marks `id` as acting, and every other badge as not. */
export const setActing = (entries: readonly Entry[], id: string | undefined): Entry[] =>
  entries.map((entry) => {
    const acting = entry.id === id && !entry.isDone
    return entry.acting === acting ? entry : { ...entry, acting }
  })

/** One badge as laid out: both parts' text with their padding, ready to draw. */
export type Badge = { id: string; name: string; status: string; isDone: boolean; acting: boolean }

export type Layout = {
  /** The badges that fit, the first on the left. */
  badges: Badge[]
  folded: number
  issues: string
  /** True when the Restart button shows before the issue count. */
  restart: boolean
  /** Blank cells between the last badge (or `+N`) and the button or issue count. */
  space: number
}

/** Blank cells between two badges. */
export const GAP = 1

/** The Restart button's label, which sits between 2 corners like a badge, and the blank cells between it and the issue count. */
export const RESTART = ' Restart '
export const RESTART_CELLS = RESTART.length + 2
export const RESTART_GAP = 2

/** How much of a badge other than the main one shows: the whole, its id and word, or its id alone. */
type Shape = 'full' | 'words' | 'ids'
const SHAPES: readonly Shape[] = ['full', 'words', 'ids']

/**
 * The corner is the only padding at each end, so the text starts at the colour's edge.
 * The status takes one space after the name's colour ends (without it the badge looked bad,
 * the user, 2026-10-18). Corners are kept at any width: without them each end would take a
 * space, the same 2 cells, so dropping them frees nothing. An id alone has no status, and a
 * closed one keeps its `✓`.
 */
function badgeOf(entry: Entry, shape: Shape): Badge {
  const word = shape === 'ids' ? (entry.isDone ? '✓' : '') : entry.word
  return {
    id: entry.id,
    name: shape === 'full' ? entry.name : entry.id,
    status: word ? ` ${word}` : '',
    isDone: entry.isDone,
    acting: entry.acting,
  }
}

/** The spinner and the space before it, drawn after the status while a badge acts. */
export const SPIN_CELLS = 2

/** Cells of a badge: its text, its 2 corners and, while it acts with the spinner on, the spinner. */
const cells = (badge: Badge, spinner: boolean) => badge.name.length + badge.status.length + 2 + (badge.acting && spinner ? SPIN_CELLS : 0)
const foldWidth = (n: number) => (n ? ` +${n}`.length : 0)

/** The badges from the left that fit `room`, which keeps its cells for the `+N` of those left out. */
function fit(badges: readonly Badge[], room: number, spinner: boolean): Badge[] {
  const shown: Badge[] = []
  let used = 0
  for (const [at, badge] of badges.entries()) {
    const width = cells(badge, spinner) + (shown.length ? GAP : 0)
    if (used + width + foldWidth(badges.length - at - 1) > room) break
    shown.push(badge)
    used += width
  }
  return shown
}

/**
 * The band in `columns` cells, one row. The right end holds the Restart button, when `restart` is
 * true, then the open Flow `issues`; they keep their cells and the badges give way. The main badge,
 * the leftmost open one, always shows whole. The others show whole while all fit, then as id and
 * word, then as id alone; what still does not fit folds. `spinner` says whether an acting badge
 * shows its spinner.
 */
export function layout(entries: readonly Entry[], columns: number, issues: number, spinner = true, restart = false): Layout {
  const count = issues ? `${issues} issue${issues > 1 ? 's' : ''}` : ''
  const right = (restart ? RESTART_CELLS + (count ? RESTART_GAP : 0) : 0) + count.length
  const room = columns - (right ? right + 2 : 0)
  const main = entries.find((entry) => !entry.isDone) ?? entries[0]
  let badges: Badge[] = []
  for (const shape of SHAPES) {
    badges = fit(entries.map((entry) => badgeOf(entry, entry === main ? 'full' : shape)), room, spinner)
    if (badges.length === entries.length) break
  }
  const folded = entries.length - badges.length
  const left = badges.reduce((n, badge, at) => n + cells(badge, spinner) + (at ? GAP : 0), 0) + foldWidth(folded)
  return { badges, folded, issues: count, restart, space: Math.max(1, columns - left - right) }
}

/** Mixes two `#rrggbb` colours: `share` of the way from `from` to `to`. */
export function mix(from: string, to: string, share: number): string {
  const channel = (hex: string, i: number) => parseInt(hex.slice(1 + i * 2, 3 + i * 2), 16)
  const out = [0, 1, 2].map((i) => Math.round(channel(from, i) + (channel(to, i) - channel(from, i)) * share))
  return `#${out.map((v) => v.toString(16).padStart(2, '0')).join('')}`
}

/** The wave's 3 cells, how far from the badge's colour toward white each one's background is. */
const WAVE = [0.35, 1, 0.35]

/**
 * The share of white in each cell's background for a name and status `length` cells long at
 * `frame`: 0 is the badge's colour. The wave moves a cell a frame from the left edge to past the
 * right edge and starts over at once.
 */
export function waveShares(length: number, frame: number): number[] {
  const start = (frame % (length + WAVE.length)) - WAVE.length
  return Array.from({ length }, (_, i) => WAVE[i - start] ?? 0)
}

/**
 * The spinner's cells: braille dots turning (the user's pick, 2026-10-18). Braille is in neither
 * terminal font (Consolas, DejaVu Sans Mono), so a fallback font draws it: if the cell shows cut,
 * the block elements `▘▀▝▐▗▄▖▌` are drawn by the terminal itself and always fit.
 */
const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

/** The spinner's cell at `frame`, a step each frame. */
export const spinnerAt = (frame: number): string => SPINNER[frame % SPINNER.length] as string

files.hooks/issues.ts:
/**
 * issues.ts: how many Flow issues are open, from the failure log.
 *
 * Repeats `open()` in `scripts/lib/logs/failures.js`, which the mod cannot require. An
 * issue is a job whose last run failed: a line with a `job` opens it and a later
 * `cleared` line for the same job closes it.
 */

/** The log files that can hold an open issue: last month's and this month's, `~/.flow/logs/failures/<year>-<month>.jsonl`. */
export function failureFiles(home: string, now: Date): string[] {
  const month = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`
  const before = new Date(now.getFullYear(), now.getMonth() - 1, 1)
  return [before, now].map((date) => `${home}/logs/failures/${month(date)}.jsonl`)
}

/** The open issues over the text of those files, oldest first. */
export function openIssues(texts: readonly string[]): number {
  const jobs = new Set<string>()
  for (const line of texts.flatMap((text) => text.split('\n'))) {
    let entry: { job?: unknown; cleared?: unknown }
    try {
      entry = JSON.parse(line)
    } catch {
      continue
    }
    if (typeof entry.job !== 'string') continue
    if (entry.cleared) jobs.delete(entry.job)
    else jobs.add(entry.job)
  }
  return jobs.size
}

files.hooks/look.ts:
/**
 * look.ts: the band's settings from `band-settings.json` in the mod folder.
 *
 * `sweep` is the pale bar running along a badge, `spinner` the braille cell after its word and
 * `topRow` the empty row above the badges. Each is on unless the file says `false`, so a missing
 * or broken file changes nothing.
 */
export type Look = { sweep: boolean; spinner: boolean; topRow: boolean }

export const DEFAULT_LOOK: Look = { sweep: true, spinner: true, topRow: true }

/** The settings in the file's text. Anything that is not `false` leaves a setting on. */
export function parseLook(text: string | undefined): Look {
  if (text === undefined) return DEFAULT_LOOK
  try {
    const raw = JSON.parse(text) as { sweep?: unknown; spinner?: unknown; topRow?: unknown } | null
    return { sweep: raw?.sweep !== false, spinner: raw?.spinner !== false, topRow: raw?.topRow !== false }
  } catch {
    return DEFAULT_LOOK
  }
}

files.hooks/record.ts:
/**
 * record.ts: the band's saved record, one `$.store` key for each session.
 *
 * `$.state` is the session's alone and a reopen empties it, so the band is written here when it
 * changes and read back at `session.start`. A record is `{ v: 1, updated, band }`: each feature
 * that joins later owns one more field and leaves the others as they are.
 */
import type { Entry } from '../types'

const PREFIX = 'session:'
const VERSION = 1
const DAY_MS = 86_400_000
export const KEEP_DAYS = 14

export type Saved = { v: number; updated: string; band: Entry[] }

export const recordKey = (sessionId: string): string => `${PREFIX}${sessionId}`
export const isRecordKey = (key: string): boolean => key.startsWith(PREFIX)

/** The record for the band as it stands. A wave is never saved: nothing runs after a reopen. */
export const makeRecord = (band: readonly Entry[], now: Date): Saved => ({
  v: VERSION,
  updated: now.toISOString(),
  band: band.map(plain),
})

const isEntry = (value: unknown): value is Entry => {
  const entry = value as Partial<Entry> | null
  return (
    typeof entry === 'object' &&
    entry !== null &&
    typeof entry.id === 'string' &&
    typeof entry.name === 'string' &&
    typeof entry.word === 'string' &&
    typeof entry.isDone === 'boolean'
  )
}

/** A badge as saved: only its own fields, so a record written with the old idle and ended counts reads the same. */
const plain = (entry: Entry): Entry => ({ id: entry.id, name: entry.name, word: entry.word, isDone: entry.isDone, acting: false })

/** What a stored value holds, or undefined when it is no record of this version. */
export function parseRecord(value: unknown): Saved | undefined {
  const record = value as Partial<Saved> | null
  if (typeof record !== 'object' || record === null || record.v !== VERSION) return undefined
  if (typeof record.updated !== 'string' || Number.isNaN(Date.parse(record.updated))) return undefined
  if (!Array.isArray(record.band) || !record.band.every(isEntry)) return undefined
  return { v: VERSION, updated: record.updated, band: record.band.map(plain) }
}

/** True when a stored value is no record, or was last written more than 14 days before `now`. */
export function isExpired(value: unknown, now: Date): boolean {
  const record = parseRecord(value)
  return !record || now.getTime() - Date.parse(record.updated) > KEEP_DAYS * DAY_MS
}

files.hooks/ticket.ts:
/**
 * ticket.ts: reads a ticket's text the way the band needs it: its name, status, word and count.
 *
 * The mod cannot require Flow's scripts, so `STEP`, `QUESTION` and the counting repeat
 * `scripts/lib/tickets/store.js`. The word is the ticket's `activity:`; without one,
 * `DESIGN` while `## Questions` has an open box, else `BUILD` while `## Tasks` has one,
 * else the status.
 */

export type Ticket = {
  id: string
  name: string
  status: string
  /** The word and the count, such as `BUILD 2/5`; no count where the ticket has no list. */
  word: string
}

type Count = { done: number; total: number }

// The same patterns as the scripts: a step sits at the left margin, a question at any indent.
const STEP = /^ {0,3}(?:\d+[.)]|[-*])\s+\[([ xX])\]/
const QUESTION = /^\s*(?:\d+[.)]|[-*])\s+\[([ xX])\]/

/** Ticked and total boxes of a text. A commented-out box is not a box. */
function countBoxes(text: string | undefined, pattern: RegExp): Count | undefined {
  if (text === undefined) return undefined
  const boxes = text
    .replace(/<!--[\s\S]*?-->/g, '')
    .split('\n')
    .map((line) => pattern.exec(line))
    .filter((match): match is RegExpExecArray => match !== null)
  return boxes.length ? { done: boxes.filter((m) => m[1] !== ' ').length, total: boxes.length } : undefined
}

/** The text under `## <heading>` up to the next `##` heading, or undefined where there is none. */
function section(body: string, heading: string): string | undefined {
  const lines = body.split('\n')
  const start = lines.findIndex((line) => line.trim() === `## ${heading}`)
  if (start === -1) return undefined
  const rest = lines.slice(start + 1)
  const end = rest.findIndex((line) => /^## /.test(line))
  return (end === -1 ? rest : rest.slice(0, end)).join('\n')
}

/** The frontmatter fields and the body after them. */
function split(text: string): { fields: Record<string, string>; body: string } {
  const lines = text.split('\n')
  if (lines[0]?.trim() !== '---') return { fields: {}, body: text }
  const end = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
  if (end === -1) return { fields: {}, body: text }
  const fields: Record<string, string> = {}
  for (const line of lines.slice(1, end)) {
    const at = line.indexOf(':')
    if (at > 0) fields[line.slice(0, at).trim()] = line.slice(at + 1).trim().replace(/^["']|["']$/g, '')
  }
  return { fields, body: lines.slice(end + 1).join('\n') }
}

const isOpen = (count?: Count) => count !== undefined && count.done < count.total
const show = (count?: Count) => (count ? `${count.done}/${count.total}` : '')

/**
 * The ticket in `text` (a `ticket.md`), or undefined where it has no id or status.
 * `map` is the text of its `groundwork/map.md`, counted for a design ticket with no questions of its own.
 */
export function readTicket(text: string, map?: string): Ticket | undefined {
  const { fields, body } = split(text)
  const { id, status } = fields
  if (!id || !status) return undefined
  const questions = countBoxes(section(body, 'Questions'), QUESTION)
  const tasks = countBoxes(section(body, 'Tasks'), STEP)
  const activity = fields.activity?.toLowerCase()
  const word = activity || (isOpen(questions) ? 'design' : isOpen(tasks) ? 'build' : status)
  const designs = word === 'design'
  const count = designs
    ? (questions ?? countBoxes(map, QUESTION) ?? tasks)
    : (tasks ?? questions ?? countBoxes(map, QUESTION))
  // A ticket with no list shows the word alone: a cause hunt has nothing to count.
  const shown = [word.toUpperCase(), activity || isOpen(questions) || isOpen(tasks) ? show(count) : ''].filter(Boolean)
  return { id, name: fields.title ? `${id}-${fields.title}` : id, status, word: shown.join(' ') }
}

/** The ticket ids a command or a path names, such as `fw-137`. */
export const idsIn = (text: string): string[] => [...new Set(text.match(/\b[a-z]+-\d+\b/g) ?? [])]

/** The ticket ids a command picks up with `flow start <id>`, in the order it names them. A bare `flow <id>` only reads. */
export const startedIn = (command: string): string[] => [...command.matchAll(/\b(?:flow|fw)\s+start\s+([a-z]+-\d+)\b/g)].map((match) => match[1] as string)

/** Where a click on a badge's word lands: a file of the ticket and a line in it, counted from 1. */
export type Target = { file: 'ticket' | 'map'; line: number }

/** The line of the first open box in `text`, or in the lines under `## <heading>` when one is named. Commented-out lines are skipped. */
function firstOpen(text: string, pattern: RegExp, heading?: string): number | undefined {
  const lines = text.split('\n')
  let inside = heading === undefined
  let commented = false
  for (const [at, line] of lines.entries()) {
    if (heading !== undefined && /^## /.test(line)) inside = line.trim() === `## ${heading}`
    if (commented || line.includes('<!--')) commented = !line.includes('-->')
    else if (inside && pattern.exec(line)?.[1] === ' ') return at + 1
  }
  return undefined
}

/**
 * Where the word of `ticket` points: `BUILD` at the first open task, `DESIGN` at the first open
 * question (the map's, when the ticket has none), any other word at the top of the ticket.
 */
export function target(ticket: string, map: string | undefined, word: string): Target {
  const top: Target = { file: 'ticket', line: 1 }
  const first = word.split(' ')[0]?.toLowerCase()
  if (first === 'build') {
    const line = firstOpen(ticket, STEP, 'Tasks')
    return line ? { file: 'ticket', line } : top
  }
  if (first === 'design') {
    const line = firstOpen(ticket, QUESTION, 'Questions')
    if (line) return { file: 'ticket', line }
    const inMap = map === undefined ? undefined : firstOpen(map, QUESTION)
    return inMap ? { file: 'map', line: inMap } : top
  }
  return top
}

